class Rechteck:
    def __init__(self, a, b):
        self.a, self.b = a, b
    def flaeche(self):
        return self.a * self.b

class Quadrat(Rechteck):
    def __init__(self, a):
        super().__init__(a, a)

for f in [Rechteck(2, 3), Quadrat(2)]:
    print(f.flaeche())

from abc import ABC, abstractmethod

class Person(ABC):
    def __init__(self, name):
        self.name = name
    @abstractmethod
    def vorstellen(self):
        ...

class Lehrer(Person):
    def gruss(self):
        return "Hallo, ich bin " + self.name

print(Lehrer("Ada").gruss())

def summe(werte: list[int]) -> int:
    ergebnis = werte[0]
    for w in werte[1:]:
        ergebnis = ergebnis + w
    return ergebnis

print(summe(["1", "2", "3"]))

A = TypeVar("A")
B = TypeVar("B")

def tausche(p: tuple[A, B]) -> tuple[B, A]:
    return (p[1], p[0])

p = tausche(("Max", 17))
